 "content": "def transform(grid):
    """Count isolated 4-cell T tetrominoes by stem direction and encode counts."""
    h, w = len(grid), len(grid[0])
    seen = set()
    up = down = 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 2 and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            if len(comp) != 4:
                continue
            cells = set(comp)
            rows = sorted({y for y, x in cells})
            cols = sorted({x for y, x in cells})
            # A T consists of a length-three horizontal bar and its central stem.
            if len(rows) == 2 and len(cols) == 3:
                top, bot = rows
                if bot == top + 1 and all((top, x) in cells for x in cols) and cols[1] == cols[0] + 1 and cols[2] == cols[1] + 1:
                    if (bot, cols[1]) in cells:
                        down += 1
                    continue
                if bot == top + 1 and all((bot, x) in cells for x in cols) and cols[1] == cols[0] + 1 and cols[2] == cols[1] + 1:
                    if (top, cols[1]) in cells:
                        up += 1
                    continue
    out = [[0] * 6 for _ in range(3)]
    # Counts are represented column-major in each 2x2 block, using 3 for up and 1 for down.
    slots = ((0, 0), (2, 0), (0, 2), (2, 2))
    for i in range(min(up, 4)):
        y, x = slots[i]
        out[y][x] = 3
    for i in range(min(down, 4)):
        y, x = slots[i]
        out[y][x + 3] = 1
    return out
